settings.custom_liquid:
{%- comment -%}
  Vérifier si le produit est dans les collections Black Friday
{%- endcomment -%}
{% assign in_black_friday = false %}
{% assign in_extended_black_friday = false %}

{% for coll in product.collections %}
  {% if coll.id == 665091113340 %}
    {% assign in_black_friday = true %}
  {% elsif coll.id == 677847957884 %}
    {% assign in_extended_black_friday = true %}
  {% endif %}
{% endfor %}

{%- comment -%}
  Afficher uniquement si le produit est dans l'une des deux collections
{%- endcomment -%}
{% if in_black_friday or in_extended_black_friday %}

  {% if in_black_friday %}
    <div class="mp-bf-message">
      <p><strong>{{ 'bf.last_hours_title' | t }}</strong></p>
      <p><strong>{{ 'bf.last_hours_subtitle' | t }}</strong></p>
    </div>

  {% elsif in_extended_black_friday %}
    <div class="mp-bf-message">
      <p><strong>{{ 'bf.extended_title' | t }}</strong></p>
      <p><strong>{{ 'bf.extended_subtitle' | t }}</strong></p>
    </div>
  {% endif %}

  <div id="mp-countdown-wrapper">
    <div id="mp-countdown">
      <div class="mp-item">
        <div class="mp-box" id="mp-days">00</div>
        <div class="mp-label">{{ 'countdown.days' | t }}</div>
      </div>
      <div class="mp-item">
        <div class="mp-box" id="mp-hours">00</div>
        <div class="mp-label">{{ 'countdown.hours' | t }}</div>
      </div>
      <div class="mp-item">
        <div class="mp-box" id="mp-minutes">00</div>
        <div class="mp-label">{{ 'countdown.minutes' | t }}</div>
      </div>
      <div class="mp-item">
        <div class="mp-box" id="mp-seconds">00</div>
        <div class="mp-label">{{ 'countdown.seconds' | t }}</div>
      </div>
    </div>
  </div>

  <script>
    // Cible : 1 décembre 2025 à 23:59 heure française (Europe/Paris)
    const targetDate = new Date("2025-12-02T22:59:00.000Z"); 
    // 23:59 Paris = 22:59 UTC en hiver

    function updateCountdown() {
      const now = new Date().getTime();
      let distance = targetDate.getTime() - now;

      if (distance <= 0) {
        distance = 0;
      }

      const days = Math.floor(distance / (1000 * 60 * 60 * 24));
      const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((distance % (1000 * 60)) / 1000);

      document.getElementById("mp-days").textContent = String(days).padStart(2, "0");
      document.getElementById("mp-hours").textContent = String(hours).padStart(2, "0");
      document.getElementById("mp-minutes").textContent = String(minutes).padStart(2, "0");
      document.getElementById("mp-seconds").textContent = String(seconds).padStart(2, "0");
    }

    setInterval(updateCountdown, 1000);
    updateCountdown();
  </script>

  <style>
.mp-bf-message {
  max-width: 680px;
  margin: 0 auto 10px auto;
  text-align: center;
  color: black !important;
  font-family: "Helvetica Neue", sans-serif;
  font-size: 14px;
  line-height: 1.25;
  font-weight: 400;
  padding: 0;
}

.mp-bf-message p {
  margin: 4px 0;
  padding: 0;
}

#mp-countdown-wrapper {
  display: flex;
  justify-content: center;
  background: transparent !important;
}

#mp-countdown {
  display: flex;
  gap: 20px;
  justify-content: center;
  align-items: flex-start;
  flex-wrap: wrap;
  background: transparent !important;
}

.mp-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: transparent !important;
}

.mp-box {
  background: white !important;
  color: black !important;
  border-radius: 10px;
  width: 65px;
  height: 65px;
  font-size: 26px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
}

.mp-label {
  font-size: 12px;
  letter-spacing: 1px;
  margin-top: 6px;
  color: black;
  font-family: "Helvetica Neue", sans-serif;
  text-align: center;
}

.mp-bf-message {
  max-width: 760px;
  margin: 0 auto 20px auto;
  text-align: center;
  color: white;
  font-family: "Helvetica Neue", sans-serif;
  font-size: 14px;
  line-height: 1.5;
}

@media (max-width: 768px) {
  #mp-countdown {
    gap: 12px;
  }
  .mp-box {
    width: 50px;
    height: 50px;
    font-size: 20px;
  }
  .mp-label {
    font-size: 10px;
    margin-top: 4px;
  }
  .mp-bf-message {
    font-size: 13px;
    padding: 0 10px;
  }
}

@media (max-width: 400px) {
  #mp-countdown {
    gap: 8px;
  }
  .mp-box {
    width: 45px;
    height: 45px;
    font-size: 18px;
  }
  .mp-label {
    font-size: 9px;
    margin-top: 3px;
  }
  .mp-bf-message {
    font-size: 12px;
  }
}
  </style>

{% endif %}

{%- if product.metafields.custom.bestseller.value == 'imparfait' -%}
