{% assign target_collection = collections['reward-ready'] %}

{% if target_collection != empty %}
  {% assign raw_count = target_collection.all_products_count %}
  {% comment %} Arrondi à la dizaine inférieure : 888 devient 880 {% endcomment %}
  {% assign rounded_count = raw_count | divided_by: 10 | times: 10 %}
{% else %}
  {% comment %} Fallback si le handle est mauvais : on met 500 par défaut {% endcomment %}
  {% assign rounded_count = 500 %}
{% endif %}

{% if product.tags contains 'reward-ready' %}
  <div class="loyalty-info">
    <p>{{ 'loyalty.reward_ready.description' | t }}</p>
    <ul>
      <li>
        {% comment %} Le lien ne s'affichera que si la collection est trouvée {% endcomment %}
        <a href="{{ target_collection.url }}" class="loyalty-link-offer">
          {{ 'loyalty.reward_ready.offer_1' | t: count: rounded_count }}
        </a>
      </li>
      <li>{{ 'loyalty.reward_ready.offer_2' | t }}</li>
      <li>{{ 'loyalty.reward_ready.offer_3' | t }}</li>
    </ul>

{% elsif product.tags contains 'cashback' %}
  <div class="loyalty-info">
    <p>{{ 'loyalty.cashback.description' | t }}</p>
{% endif %}

  <p>{{ 'loyalty.conditions.notice' | t }}</p> 

